            return memo[(pos, visited)]

        next_pos = plaques[pos]
        result = dfs(next_pos, visited | (1 << (next_pos - 1)), start, steps - 1)
        memo[(pos, visited)] = result
        return result

    count = 0
    for mask in range(1 << n):
        plaques = [0] * (n + 1)
        for i in range(1, n + 1):
            if mask & (1 << (i - 1)):
                plaques[i] = i
            else:
                plaques[i] = n + 1 - i

        memo = {}
        valid = True
        for i in range(1, k + 1):
            if dfs(i, 0, i, n) == 0:
                valid = False
                break
        for i in range(k + 1, n + 1):
            if dfs(i, 0, i, n) > 0:
                valid = False
                break

        if valid:
            count += 1

    return count % MOD

