    def dfs(node, visited, stack):
        visited[node] = True
        stack[node] = True
        next_node = plaques[node]
        if not visited[next_node]:
            if dfs(next_node, visited, stack):
                return True
        elif stack[next_node]:
            return True
        stack[node] = False
        return False

    def count_cycles():
        visited = [False] * (n + 1)
        stack = [False] * (n + 1)
        cycle_count = 0
        for node in range(1, n + 1):
            if not visited[node]:
                if dfs(node, visited, stack):
                    cycle_count += 1
        return cycle_count

    def count_paths_to_one():
        paths = [0] * (n + 1)
        paths[1] = 1
        for i in range(1, n + 1):
            if paths[i] > 0:
                next_house = plaques[i]
                paths[next_house] = (paths[next_house] + paths[i]) % MOD
        return sum(paths[1:k+1]) % MOD

    def count_configurations():
        cycle_count = count_cycles()
        if cycle_count == 0:
            return 1
        else:
            return pow(cycle_count, MOD - 2, MOD)

    plaques = [0] * (n + 1)
    for i in range(1, n + 1):
        plaques[i] = i

    paths_to_one = count_paths_to_one()
    config_count = count_configurations()

    return (paths_to_one * config_count) % MOD

