    MOD = 1000000007

    # dp[house][walks] = number of ways to configure house with walks remaining
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Base case: starting from house 1, we can always return to house 1
    dp[1][0] = 1

    # Fill the dp table
    for house in range(1, n + 1):
        for walks in range(k + 1):
            if dp[house][walks] > 0:
                next_house = p[house]
                if walks < k:
                    dp[next_house][walks + 1] = (dp[next_house][walks + 1] + dp[house][walks]) % MOD

    # Calculate the number of valid configurations
    result = 0
    for house in range(1, n + 1):
        for walks in range(k + 1):
            if house == 1 and walks > 0:
                result = (result + dp[house][walks]) % MOD
            elif house > k:
                result = (result + dp[house][walks]) % MOD

    return result

